1	// The admin's settings in one JSON file. No Hono import: plain Node + the shared schema.
2	import { randomUUID } from "node:crypto";
3	import { mkdir, readFile, rename, unlink, writeFile } from "node:fs/promises";
4	import { dirname } from "node:path";
5	import { AdminSettingsSchema, type AdminSettings } from "@organic/shared";
6	
7	export interface AdminSettingsStore {
8	  read(): Promise<AdminSettings>;
9	  /** Read → mutate → write as one step, so two concurrent toggles never lose an update. */
10	  update(mutate: (current: AdminSettings) => AdminSettings): Promise<AdminSettings>;
11	}
12	
13	function isMissingFile(error: unknown): boolean {
14	  return (error as NodeJS.ErrnoException | null)?.code === "ENOENT";
15	}
16	
17	export function createAdminSettingsStore(filePath: string, defaults: AdminSettings): AdminSettingsStore {
18	  // One promise chain for the file: `then(op, op)` keeps the queue alive after a failed write.
19	  let queue: Promise<unknown> = Promise.resolve();
20	
21	  async function readFileOrDefaults(): Promise<AdminSettings> {
22	    let raw: string;
23	    try {
24	      raw = await readFile(filePath, "utf8");
25	    } catch (error) {
26	      // No file yet means the admin has never saved anything; anything else is a real failure.
27	      if (isMissingFile(error)) return structuredClone(defaults);
28	      throw error;
29	    }
30	    // A file that does not parse is never rewritten: the admin answers 500 until a human fixes it.
31	    return AdminSettingsSchema.parse(JSON.parse(raw));
32	  }
33	
34	  async function write(next: AdminSettings): Promise<void> {
35	    await mkdir(dirname(filePath), { recursive: true });
36	    const tmp = `${filePath}.${randomUUID()}.tmp`;
37	    try {
38	      await writeFile(tmp, JSON.stringify(next, null, 2));
39	      // Same directory, so the replace is atomic: a reader sees the old or the new file, never a partial one.
40	      await rename(tmp, filePath);
41	    } catch (error) {
42	      await unlink(tmp).catch(() => undefined);
43	      throw error;
44	    }
45	  }
46	
47	  function enqueue<T>(operation: () => Promise<T>): Promise<T> {
48	    const next = queue.then(operation, operation);
49	    queue = next.catch(() => undefined);
50	    return next;
51	  }
52	
53	  return {
54	    // No in-memory cache: the file is a few hundred bytes and a manual edit must be picked up.
55	    read: () => enqueue(readFileOrDefaults),
56	    update: (mutate) =>
57	      enqueue(async () => {
