1	import {
2	  AdminProductsResponseSchema,
3	  AdminSessionSchema,
4	  AdminSettingsSchema,
5	  BasketResponseSchema,
6	  CatalogResponseSchema,
7	  ProductVisibilityResponseSchema,
8	  type AdminProductsResponse,
9	  type AdminSession,
10	  type AdminSettings,
11	  type BasketResponse,
12	  type CatalogResponse,
13	  type ProductVisibilityResponse,
14	  type UpdateAdminSettings,
15	} from "@organic/shared";
16	
17	/** Carries the HTTP status, so a caller tells 401 from 503 without parsing the message. */
18	export class ApiError extends Error {
19	  constructor(
20	    method: string,
21	    path: string,
22	    readonly status: number,
23	  ) {
24	    super(`${method} ${path} failed: ${status}`);
25	    this.name = "ApiError";
26	  }
27	}
28	
29	/** Every server call goes through this module, so component tests mock one module. */
30	export async function getProducts(): Promise<CatalogResponse> {
31	  const response = await fetch("/api/products");
32	  if (!response.ok) throw new Error(`GET /api/products failed: ${response.status}`);
33	  return CatalogResponseSchema.parse(await response.json());
34	}
35	
36	/**
37	 * The basket id and the admin session live in httpOnly cookies, so every call sends credentials.
38	 * `schema` is typed structurally (every zod schema satisfies it): `zod` is a dependency of
39	 * `@organic/shared` only and does not resolve from apps/web.
40	 */
41	async function request<T>(
42	  method: string,
43	  path: string,
44	  options: { schema?: { parse(input: unknown): T }; body?: unknown } = {},
45	): Promise<T> {
46	  const { schema, body } = options;
47	  const response = await fetch(path, {
48	    method,
49	    credentials: "same-origin",
50	    headers: body !== undefined ? { "Content-Type": "application/json" } : undefined,
51	    body: body !== undefined ? JSON.stringify(body) : undefined,
52	  });
53	  if (!response.ok) throw new ApiError(method, path, response.status);
54	  // No schema means a 204 answer: there is nothing to parse.
55	  return schema === undefined ? (undefined as T) : schema.parse(await response.json());
56	}
57	
58	/**
59	 * Percent-encodes a product id for a path segment, except the ":" between shop key and source id:
60	 * RFC 3986 allows it literally in a path segment and the basket and admin paths are pinned to that form.
61	 */
62	const encodeProductId = (productId: string): string =>
63	  encodeURIComponent(productId).replaceAll("%3A", ":");
64	
65	const itemPath = (productId: string): string => `/api/basket/items/${encodeProductId(productId)}`;
66	
67	export const getBasket = (): Promise<BasketResponse> =>
68	  request("GET", "/api/basket", { schema: BasketResponseSchema });
69	
70	// Every mutation answers the whole basket, so the caller never needs a second getBasket().
71	export const addToBasket = (productId: string, quantity: number): Promise<BasketResponse> =>
72	  request("POST", "/api/basket/items", { schema: BasketResponseSchema, body: { productId, quantity } });
73	
74	export const updateBasketItem = (productId: string, quantity: number): Promise<BasketResponse> =>
75	  request("PATCH", itemPath(productId), { schema: BasketResponseSchema, body: { quantity } });
76	
77	export const removeBasketItem = (productId: string): Promise<BasketResponse> =>
78	  request("DELETE", itemPath(productId), { schema: BasketResponseSchema });
79	
80	export const clearBasket = (): Promise<BasketResponse> =>
81	  request("DELETE", "/api/basket", { schema: BasketResponseSchema });
82	
83	export const getAdminSession = (): Promise<AdminSession> =>
84	  request("GET", "/api/admin/session", { schema: AdminSessionSchema });
85	
86	export const adminLogin = (token: string): Promise<void> =>
87	  request<void>("POST", "/api/admin/login", { body: { token } });
88	
89	export const adminLogout = (): Promise<void> => request<void>("POST", "/api/admin/logout");
90	
91	export const getAdminSettings = (): Promise<AdminSettings> =>
