12	import { createAdminSettingsStore, type AdminSettingsStore } from "../lib/store/admin-settings";
13	import { createBasketStore } from "../lib/store/baskets";
14	import type { ShopAdapter } from "../shops/types";
15	
16	// The committed snapshots in data/shops/, passed as a value; snapshot mode reads them, the fakes never answer.
17	const snapshotDir = fileURLToPath(new URL("../../../../data/shops", import.meta.url));
18	
19	const KARASHYNYARD_SHOP = {
20	  key: "karashynyard",
21	  name: "Карашин Яр",
22	  url: "https://karashynyard.com.ua/#rec638772397",
23	} as const;
24	const OSIO_SHOP = { key: "osio", name: "OSIO organic", url: "https://osio-organic.com.ua/" } as const;
25	
26	const SNAPSHOT_DEFAULTS: AdminSettings = { dataSource: "snapshot", visibility: { karashynyard: null, osio: null } };
27	
28	// The exact settings files of the scenarios.
29	const CHOSEN_TWO_FILE =
30	  '{"dataSource":"snapshot","visibility":{"karashynyard":["karashynyard:1743423686258","karashynyard:1498486363994"],"osio":null}}';
31	const PERSISTED_SNAPSHOT_FILE = '{"dataSource":"snapshot","visibility":{"karashynyard":null,"osio":null}}';
32	
33	const dirs: string[] = [];
34	
35	function tempDir(prefix: string): string {
36	  const dir = mkdtempSync(join(tmpdir(), prefix));
37	  dirs.push(dir);
38	  return dir;
39	}
40	
41	afterEach(() => {
42	  for (const dir of dirs.splice(0)) rmSync(dir, { recursive: true, force: true });
43	});
44	
45	/** A settings store on a fresh temp directory, optionally seeded with the scenario's file. */
46	function newSettingsStore(json: string | undefined, defaults: AdminSettings = SNAPSHOT_DEFAULTS) {
47	  const dir = tempDir("admin-settings-");
48	  if (json !== undefined) writeFileSync(join(dir, "admin-settings.json"), json);
49	  return createAdminSettingsStore(join(dir, "admin-settings.json"), defaults);
50	}
51	
52	/** The app of products.test.ts (fake adapters, committed snapshots) over the given settings store. */
53	function appOver(store: AdminSettingsStore, source: DataSource) {
54	  const karashynyard = vi.fn<ShopAdapter["fetchProducts"]>();
55	  const osio = vi.fn<ShopAdapter["fetchProducts"]>();
56	  const catalog = createCatalogService({
57	    source,
58	    shops: [
59	      { adapter: { shop: KARASHYNYARD_SHOP, fetchProducts: karashynyard }, snapshotKey: "karashynyard" },
60	      { adapter: { shop: OSIO_SHOP, fetchProducts: osio }, snapshotKey: "osio" },
61	    ],
62	    snapshots: createSnapshotSource(snapshotDir),
63	    cache: createTtlCache({ ttlMs: 300000, now: () => 0 }),
64	    now: () => 0,
65	    settings: store,
66	  });
67	  const basketStore = createBasketStore(join(tempDir("baskets-"), "baskets.json"));
68	  const app = createApp({ catalog, basketStore, settingsStore: store, adminToken: undefined });
69	  return { app, catalog, karashynyard, osio };
70	}
71	
72	/** A snapshot-mode app whose settings file is `json` (none = the snapshot defaults). */
73	function appOverSettings(json?: string) {
74	  const store = newSettingsStore(json);
75	  return { store, ...appOver(store, "snapshot") };
76	}
77	
78	const products = async (app: ReturnType<typeof createApp>) => {
79	  const res = await app.request("/api/products");
80	  return { res, body: (await res.json()) as CatalogResponse };
81	};
82	
83	test("Catalog honours the admin's visibility", async () => {
84	  const { app, karashynyard, osio } = appOverSettings(CHOSEN_TWO_FILE);
85	
86	  const { res, body } = await products(app);
87	
88	  expect(res.status).toBe(200);
89	  expect(body.shops[0]).toEqual({
90	    key: "karashynyard",
91	    name: "Карашин Яр",
92	    url: "https://karashynyard.com.ua/#rec638772397",
93	    status: "snapshot",
94	    count: 2,
95	  });
96	  expect(body.shops[1]).toEqual({
97	    key: "osio",
98	    name: "OSIO organic",
99	    url: "https://osio-organic.com.ua/",
100	    status: "snapshot",
101	    count: 10,
102	  });
103	  expect(body.products).toHaveLength(12);
104	  expect(body.products[0]).toMatchObject({ id: "karashynyard:1498486363994", price: 665 });
105	  expect(body.products[1]).toMatchObject({ id: "karashynyard:1743423686258", price: 480 });
106	  expect(body.products[2]?.id).toBe("osio:6abcf192b7db2532803d266d");
107	  expect(body.products[11]?.id).toBe("osio:69e5236361852dec4059d4e8");
108	  expect(karashynyard).not.toHaveBeenCalled();
109	  expect(osio).not.toHaveBeenCalled();
110	});
111	
112	test("A visibility change is served without restart", async () => {
113	  const { app, store } = appOverSettings(CHOSEN_TWO_FILE);
114	  const before = await products(app);
115	  expect(before.body.shops[0]?.count).toBe(2);
116	
117	  // The store is written behind the running app's back: the next request must pick it up.
118	  await store.update((current) => ({ ...current, visibility: { ...current.visibility, karashynyard: null } }));
119	  const { body } = await products(app);
120	
121	  expect(body.shops[0]?.count).toBe(10);
122	  expect(body.products).toHaveLength(20);
123	  expect(body.products[9]).toMatchObject({ id: "karashynyard:1743423686258", price: 480 });
124	});
125	
126	test("Persisted data source overrides DATA_SOURCE", async () => {
127	  // The server's defaults: `dataSource` from the config (DATA_SOURCE unset = live), both shops null.
128	  const defaults: AdminSettings = {
129	    dataSource: loadConfig({}).dataSource,
130	    visibility: { karashynyard: null, osio: null },
131	  };
132	  expect(defaults.dataSource).toBe("live");
133	  const store = newSettingsStore(PERSISTED_SNAPSHOT_FILE, defaults);
134	
135	  // The startup sequence of server.ts: read the settings, seed the catalog's source from them.
136	  const settings = await store.read();
137	  const { app, catalog, karashynyard, osio } = appOver(store, settings.dataSource);
138	  const { body } = await products(app);
139	
140	  expect(settings.dataSource).toBe("snapshot");
141	  expect(catalog.getSource()).toBe("snapshot");
142	  expect(body.source).toBe("snapshot");
143	  expect(body.shops).toMatchObject([
144	    { key: "karashynyard", status: "snapshot", count: 10 },
145	    { key: "osio", status: "snapshot", count: 10 },
146	  ]);
147	  expect(karashynyard).not.toHaveBeenCalled();
148	  expect(osio).not.toHaveBeenCalled();
149	
150	  // No file: DATA_SOURCE (here the config default) wins.
151	  const empty = newSettingsStore(undefined, defaults);
152	  await expect(empty.read()).resolves.toMatchObject({ dataSource: "live" });
153	});
